mkdir -p /tmp/theme-check && cat > src/__theme_check.test.tsx <<'EOF'
// @vitest-environment jsdom
import { describe, it, expect, afterEach } from 'vitest';
import { render, screen, fireEvent, cleanup } from '@testing-library/react';
import { App } from './App';

afterEach(cleanup);

describe('theme switch', () => {
  it('toggles body root class between light and dark', () => {
    render(<App />);
    const body = document.body;
    const sw = screen.getByRole('checkbox');
    console.log('INITIAL BODY CLASS:', body.className);
    expect(body.className).toMatch(/root_theme_light/);
    expect((sw as HTMLInputElement).checked).toBe(false);

    fireEvent.click(sw);
    console.log('AFTER ON BODY CLASS:', body.className);
    expect(body.className).toMatch(/root_theme_dark/);
    expect(body.className).not.toMatch(/root_theme_light/);
    expect((sw as HTMLInputElement).checked).toBe(true);
    expect(screen.getByText(/тёмная/)).toBeTruthy();

    fireEvent.click(sw);
    console.log('AFTER OFF BODY CLASS:', body.className);
    expect(body.className).toMatch(/root_theme_light/);
    expect(body.className).not.toMatch(/root_theme_dark/);
  });
});
EOF
timeout 170 npx vitest run src/__theme_check.test.tsx 2>&1 | tail -40

